        const std::size_t aIndexD = (0U * W_KEY) + ((aIndex + 1420U) & W_KEY1);

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aFoldLaneA[aIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aFoldLaneB[aIndexB]) << 8U;
